<script setup>
import { computed } from 'vue';
const props = defineProps({ modelValue: [String, Number], label: String, placeholder: String, error: String, helper: String, required: Boolean, disabled: Boolean, type: { type: String, default: 'text' }, size: { type: String, default: 'md' }, inputClass: String, autocomplete: String, id: String });
const emit = defineEmits(['update:modelValue']);
const inputId = computed(() => props.id || `input-${Math.random().toString(36).slice(2)}`);
</script>
<template><div><label v-if="label" :for="inputId" class="mb-1.5 block text-sm font-medium text-[#172033]">{{ label }} <span v-if="required" class="text-red-500">*</span></label><div class="relative"><span v-if="$slots.prefix" class="absolute inset-y-0 left-3 flex items-center text-[#9CA3AF]"><slot name="prefix" /></span><input :id="inputId" :value="modelValue" :type="type" :placeholder="placeholder" :disabled="disabled" :required="required" :autocomplete="autocomplete" :class="['ui-field px-3 placeholder:text-[#9CA3AF]', inputClass, size === 'lg' && 'h-10 text-sm', $slots.prefix && 'pl-9', $slots.suffix && 'pr-10', error && 'ui-field--error']" @input="emit('update:modelValue', $event.target.value)" /><span v-if="$slots.suffix" class="absolute inset-y-0 right-3 flex items-center text-[#9CA3AF]"><slot name="suffix" /></span></div><p v-if="error" class="mt-1 text-xs text-[#DC2626]">{{ error }}</p><p v-else-if="helper" class="mt-1 text-xs text-[#667085]">{{ helper }}</p></div></template>
